package dev.fenn.imessage.registration

import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals

/** Synthetic vectors for the NAC stamp assembly (expected outputs from nac_mint.py). */
class NacValidationTest {

    private fun stream(seed: Int, n: Int): ByteArray {
        val out = ArrayList<Byte>(n)
        var x = seed.toLong() and 0xffffffffL
        while (out.size < n) {
            x = (1103515245L * x + 12345L) and 0xffffffffL
            out.add((x and 0xff).toByte())
            out.add(((x ushr 8) and 0xff).toByte())
            out.add(((x ushr 16) and 0xff).toByte())
            out.add(((x ushr 24) and 0xff).toByte())
        }
        return out.toByteArray().copyOf(n)
    }

    private fun hex(s: String): ByteArray =
        ByteArray(s.length / 2) { ((Character.digit(s[it * 2], 16) shl 4) or
            Character.digit(s[it * 2 + 1], 16)).toByte() }

    private fun toHex(b: ByteArray): String = b.joinToString("") { "%02x".format(it) }


    @Test
    fun mintMatchesModel() {
        val cert = hex("20e91cfed93217709ef434387f7b48614c77b74495233fb9aabcf7769b50733838bc8ade1164bbd176f96c1b775bacc8e4634bea4d30e1e0023727451338017250da4c1b49841d344ec155086f42bd")
        val session = hex("")
        val pad = hex("b39a56bc709874ade937b7b76efc41730f2f16599ccb62e5a569c2db7a7195682bad90ce88059fe221fb94c0462b790007f1ea5c34f2e2575d28a519d2b58c12a396bbb7a0fdd64759ed90e11e5ddc5efff9662bcc533ef51506da042a2ded871b373bbcb8e0e2a991ee61fcf6f188a1f7294c1b64504100cde2a59382374ae0936e")
        val rand = hex("fa85a981ab675cf5086e3039a179553d")
        val sig = hex("67d46fc31402ffb7bd2aaeb9b2f85b2b")
        val expected = hex("")
        assertContentEquals(expected, NacValidation.mintWithSig(cert, session, pad, rand, sig))
    }

    @Test
    fun mintStampLayout() {
        val cert = stream(51, 79)
        val session = stream(52, 250)
        val pad = stream(53, 130)
        val rand = stream(54, 16)
        val sig = stream(55, 16)
        val stamp = NacValidation.mintWithSig(cert, session, pad, rand, sig)
        assertEquals(517, stamp.size)
        assertEquals(2, stamp[0].toInt() and 0xff)
        assertContentEquals(rand, stamp.copyOfRange(1, 17))
        assertContentEquals(sig, stamp.copyOfRange(17, 33))
        assertEquals(480, ((stamp[33].toInt() and 0xff) shl 24) or
            ((stamp[34].toInt() and 0xff) shl 16) or
            ((stamp[35].toInt() and 0xff) shl 8) or (stamp[36].toInt() and 0xff))
        assertEquals(5, stamp[37].toInt() and 0xff)
        assertEquals(79, ((stamp[434].toInt() and 0xff) shl 24) or
            ((stamp[435].toInt() and 0xff) shl 16) or
            ((stamp[436].toInt() and 0xff) shl 8) or (stamp[437].toInt() and 0xff))
        assertContentEquals(cert, stamp.copyOfRange(438, 517))
    }

    @Test
    fun mintFullE2eMatchesModel() {
        // full mint e2e: python model computed stamp517 = mint(cert79, session250, rngPad130,
        // body576, rand16) in one shot (session 21; no capture-derived bytes)
        val cert = hex("14bec976bd364823b2149b59033c029b80a78edbb981c6fffec921b15f95626facbbf61c758044550a88cc3c7b2845f698e6e977f1ae6944d61ab3d357d1f3cc44d4e28d2d49d9f6620e9e54f32b7a")
        val session = hex("")
        val pad = hex("ee5a56fa8f6b8da81c8e965a253a0f77fa37d1b2ab317fa708708ce7a1531e0fc6d9ea3c873d7d33b4847cf2dd88ab8652ccaa92232b66562038b72ad9d5dc8b9e5b05557f5666cf4cb627a295f63b6faa93e72d9bdb137a38eb3f3c116732467640034777964a0be482a41f4d6345b902ee5a611323c8bf50e9989649e7117a4ee8")
        val body = hex("")
        val rand = hex("a76f0335549ca560fd571dd9f2bcfbac")
        val expected = hex("")
        val stamp = NacValidation.mint(cert, session, pad, rand, body)
        assertEquals(517, stamp.size)
        assertContentEquals(expected.copyOfRange(17, 33), stamp.copyOfRange(17, 33))
        assertContentEquals(expected, stamp)
    }

    /** The pre-2026-10-17 model vectors were computed under establishKey(K); the API now
     *  keys under establishKey(SBOX(seed)), so the equivalent seed is SBOX⁻¹(K). */
    private fun seedForModelKey(pearKey: ByteArray): ByteArray {
        val sbox = PearTables.nacSbox
        val inv = ByteArray(256).also { i -> for (v in 0 until 256) i[sbox[v].toInt() and 0xff] = v.toByte() }
        return ByteArray(16) { inv[pearKey[it].toInt() and 0xff] }
    }

    @Test
    fun nacSboxMatchesLiveDraw() {
        // 2026-10-17 live watchpoint run: ValidationCtx::new's draw -> SBOX -> ctx[0x30],
        // and the EstablishKeyResponse decrypts to 0240 under establishKey of exactly this.
        val draw = hex("21a2f79df05b1eb8f6b4c82a66caf158")
        val x = ByteArray(16) { PearTables.nacSbox[draw[it].toInt() and 0xff] }
        assertContentEquals(hex("b79cbbe8f575c3b0fb03cf4ae02eb5d4"), x)
    }

    @Test
    fun keyEstablishmentMatchesModel() {
        val pearKey = hex("aebfc2884fd1e6ffdc60273be5756ff5")
        val sessionInfo = hex("")
        val expected = hex("")
        val pt = NacValidation.keyEstablishment(sessionInfo, seedForModelKey(pearKey))
        assertContentEquals(expected, pt)
        assertEquals(592, pt.size)
    }

    @Test
    fun keyEstablishmentFullSplitsPayloadAndTrailing() {
        // the full variant (2026-10-08 live-run mapping): payload = the SDAT-mapped
        // EstablishKeyResponse wire; trailing = the response's verbatim tail (85 B live)
        // whose first 0x4f bytes are the mint's cert79
        val pearKey = hex("aebfc2884fd1e6ffdc60273be5756ff5")
        val sessionInfo = hex("")
        val full = NacValidation.keyEstablishmentFull(sessionInfo, seedForModelKey(pearKey))
        assertContentEquals(NacValidation.keyEstablishment(sessionInfo, seedForModelKey(pearKey)), full.payload)
        assertEquals(85, full.trailing.size)
        assertContentEquals(
            sessionInfo.copyOfRange(sessionInfo.size - 85, sessionInfo.size),
            full.trailing,
        )
        // body576 = payload[2:578] (the ctx [0x40:0x280] region, wire-verified ×3 live)
        assertEquals(592, full.payload.size)
    }

    /**
     * LIVE vector (2026-10-14, gdb): the vendored client's sign() inputs captured at
     * ValidationCtx::sign entry (body576 = ctx[0x40:0x280]) with the blob480 + sig16
     * recovered from the byte-exact accepted prefpane request's X-Mme-Nas-Qualify stamp.
     * sign() must reproduce the vendor's sig16 exactly — the session-29 closing experiment
     * (mint signature exonerated on live data; the residual 400 gate is server-side).
     */
    @Test
    fun signMatchesLiveVendoredSignature() {
        val body576 = hex("")
        val blob480 = hex("")
        val rand16 = hex("8643e3aad31555888fd5062958aa5b45")
        val sig16 = NacSign.sign(body576, rand16, blob480)
        assertContentEquals(hex("243a5125f615b468975318a233a9a1fa"), sig16)
    }

    /**
     * LIVE full-mint replay (2026-10-16): the accepted prefpane stamp
     * (stamp-from-req2-001) reproduced end to end from its own recovered inputs —
     * body576 from the sign-entry ctx dump, session250 == the genuine descrambler's
     * inversion of the stamp's scrambled region, rngPad130 recovered by inverting the
     * scramble chain with the genuine .so's domergestep2 (dm(x, in2) = state(in2) XOR x,
     * so the chain is XOR-invertible), rand16/cert79 read back from the stamp. Proves the
     * Kotlin mint as a COMPOSITION on live inputs (the synthetic e2e vector above was
     * generated by the Python model and cannot catch a shared transcription error).
     */
    @Test
    fun mintReproducesLiveVendoredStamp() {
        val cert79 = hex("019a2c776657740f6777fa683f187bb66514701976000000360101a53e26262f1c4d611eb6a2b5cad938c56acf3d76c20216e7eb1e92d816c0a336b59ab58f6e5f8d3232977e95b64a913a117a0105")
        val session250 = hex("")
        val rngPad130 = hex("29d1aa55c85169c9ca1b1a0138d6dd039d6dab588b1fdad82ccad8481e3cf710c772d2e97fa36c05d9607cc94ac36eeaefe6b01acdec709ae0da535882c51b7b2b1187435f8a79d931c33d7e1e2af97bd05f3a63f7d3a8bd346e807a033f6b7c79d2a0900b1dbe604594cbb1485ef9b75d3391a8e1c99a18ba0dca9281e70bbaf144")
        val rand16 = hex("8643e3aad31555888fd5062958aa5b45")
        val body576 = hex("")
        val expected = hex("")
        val stamp = NacValidation.mint(cert79, session250, rngPad130, rand16, body576)
        assertEquals(517, stamp.size)
        assertContentEquals(expected, stamp)
    }
}
